#include "sra.h"

void* memcpy(void *dest, void *src, size_t n){

	//If length is symbolic maximize and constrain to a concrete length
	if(__is_symbolic(n)){

		size_t max = __maximize(n);
		cnstr_t maximize = _EQ_(n, max);
		__assume(maximize);
		n = max;
	}

	unsigned char *str_dest = (unsigned char*) dest;
	unsigned char *str_src = (unsigned char*) src;

	for(int i = 0; i < n; i++){

		unsigned char c = *(str_src + i);
		*(str_dest + i) = c;

	}
	return dest;
}/*Summary for libc's strcpy*/

#include "sra.h"

char* strcpy(char* dest, char* source){
	int i = 0;
	char zero = '\0';

	while(1){
		if(__is_symbolic(source[i])){

			if(!__is_sat(_NEQ_(source[i], zero))){
				break;
			}

			else{
				__assume(_NEQ_(source[i], zero));
			}
		}

		else if(source[i] == '\0'){
			break;
		}
		dest[i] = source[i];
		i++;
	}

	dest[i] = '\0';
	return dest;

}/*Summary for libc's strlen*/

#include "sra.h"

size_t strlen(char* s){

 	int i = 0;
 	char char_zero = '\0';

 	//Calculate max string length
 	while(__is_symbolic(s[i]) || s[i] != '\0'){
		i++;
 	}

	int len = i;
	symbolic ret = __sym_var(INT_SIZE);
	cnstr_t ret_cnstr = _EQ_(ret, len);

	//Build recursive ITE constraint
	for(i = len-1; i >= 0; i--){

		if(__is_symbolic(s[i])){

			cnstr_t c_eq_zero = _EQ_(s[i], char_zero);
			cnstr_t ret_eq_i = _EQ_(ret, i);

			ret_cnstr = _ITE_(c_eq_zero, ret_eq_i, ret_cnstr);

		}
	}

	__assume(ret_cnstr);
	return ret;
}lseek
